export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"ko","term":"이더리움(Ethereum, ETH)","aka":["ETH","이더","Ethereum"],"short":"이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다.","body":[[["비트코인","bitcoin"],"이 주로 송금과 가치 저장에 집중한다면, 이더리움은 프로그램을 ",["블록체인","blockchain"]," 위에 올려 실행할 수 있게 만든 네트워크입니다. ",["탈중앙화 거래소(DEX)","dex"],", 대출 서비스, ",["NFT","nft"],", ",["스테이블코인","stablecoin"]," 상당수가 이더리움에서 작동합니다."],["이더리움은 2022년 9월 머지(The Merge)를 통해 ",["작업증명","proof-of-work"],"에서 지분증명으로 전환했습니다. 이제 채굴 대신 ETH를 예치한 검증자가 블록을 만들고 보상을 받습니다. 거래나 컨트랙트 실행에는 ETH로 가스비를 내야 합니다."],"메인넷이 혼잡하면 가스비가 크게 오르기 때문에 Arbitrum, Optimism, Base 같은 레이어2 네트워크가 함께 쓰입니다. 같은 ETH라도 어떤 네트워크에 있는지에 따라 출금 방법과 수수료가 다릅니다."],"example":"ETH 가격이 3,000 USDT라고 가정하겠습니다. 이더리움 메인넷에서 토큰을 교환할 때 가스비가 0.002 ETH라면 약 6 USDT가 듭니다. 같은 작업을 레이어2에서 하면 가스비가 0.00005 ETH, 약 0.15 USDT 수준으로 줄어들 수 있습니다. 실제 가스비는 네트워크 혼잡도에 따라 계속 바뀝니다.","mistakes":["지갑에 ETH가 하나도 없는 상태에서 이더리움 기반 토큰을 보내려다 가스비 부족으로 실패합니다.","거래소에서 ETH를 출금할 때 메인넷과 레이어2 네트워크를 구분하지 않고 선택합니다.","머지 이후에도 이더리움을 채굴할 수 있다고 생각해 관련 사기 홍보에 넘어갑니다."],"faq":[{"q":"이더리움과 이더(ETH)는 다른 건가요?","a":"이더리움은 네트워크 이름이고, 이더(ETH)는 그 네트워크의 기본 코인입니다. 일상에서는 둘을 섞어 부르는 경우가 많습니다."},{"q":"이더리움은 지금도 채굴할 수 있나요?","a":"아닙니다. 2022년 9월 머지 이후 지분증명으로 바뀌어 채굴이 아니라 스테이킹과 검증자가 블록을 만듭니다."}],"title":"이더리움(ETH)이란? 뜻과 비트코인과의 차이","description":"이더리움(ETH)의 뜻, 스마트 컨트랙트와 가스비, 지분증명 전환(머지), 레이어2 네트워크와의 관계를 쉽게 정리합니다.","related":[["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["proof-of-stake","지분증명(Proof of Stake, PoS)","지분증명(PoS)은 코인을 담보로 예치한 검증자가 블록을 제안하고 검증할 자격을 얻는 블록체인 합의 방식으로, 채굴 장비 대신 예치한 지분이 보안의 근거가 됩니다."],["layer-2","레이어2(Layer 2, L2)","레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다."],["defi","디파이(DeFi, 탈중앙화 금융)","디파이(DeFi)는 은행이나 거래소 같은 중개자 없이 블록체인 위 스마트 컨트랙트로 거래, 대출, 예치 같은 금융 서비스를 제공하는 생태계입니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"ko","term":"레이어1(Layer 1, L1)","aka":["L1","레이어 1","메인넷"],"short":"레이어1(L1)은 거래의 처리와 최종 확정을 스스로 담당하는 기본 블록체인으로, 비트코인, 이더리움, 솔라나처럼 자체 합의 방식과 네이티브 코인을 가집니다.","body":["레이어1은 다른 체인에 의존하지 않고 직접 블록을 만들고 보안을 유지하는 네트워크입니다. 각 L1은 고유의 합의 방식, 블록 생성 속도, 수수료 구조, 기본 코인을 가지고 있습니다.",[["블록체인","blockchain"],"에는 탈중앙화, 보안, 확장성을 동시에 최대로 높이기 어렵다는 이른바 트릴레마가 있습니다. 어떤 L1은 ",["노드","node"]," 수와 보안을 우선하고, 어떤 L1은 빠른 처리 속도와 낮은 수수료를 우선합니다. 그래서 같은 송금이라도 체인마다 수수료와 확정 시간이 크게 다릅니다."],["L1의 처리량 한계를 보완하기 위해 그 위에 ",["레이어2","layer-2"],"를 쌓는 방식도 널리 쓰입니다. ",["거래소","centralized-exchange"],"에서 입출금할 때 선택하는 네트워크 목록에는 L1과 L2가 섞여 있으므로, 받는 쪽이 지원하는 네트워크인지 꼭 확인해야 합니다."]],"example":["같은 100 USDT를 보낼 때를 비교해 보겠습니다. A 체인에서는 수수료가 1.5 ",["USDT","usdt"],", 확정까지 약 5분이 걸리고, B 체인에서는 수수료가 0.01 USDT, 확정까지 몇 초가 걸린다고 가정합니다. 한 달에 20번 송금한다면 A는 30 USDT, B는 0.2 USDT의 수수료가 듭니다. 금액은 작아도 반복되면 ",["체인 선택","blockchain-network"],"이 비용 차이를 만듭니다."],"mistakes":["L1 이름과 그 위에서 발행된 토큰 이름을 혼동합니다.","처리 속도만 보고 체인의 보안이나 안정성은 고려하지 않습니다.","출금 네트워크를 선택할 때 받는 지갑이 해당 L1을 지원하는지 확인하지 않습니다."],"faq":[{"q":"레이어1과 레이어2의 차이는 무엇인가요?","a":"레이어1은 스스로 보안과 최종 확정을 담당하는 기본 체인이고, 레이어2는 거래를 밖에서 처리한 뒤 결과를 레이어1에 기록해 보안을 빌려 쓰는 구조입니다."},{"q":"대표적인 레이어1 코인은 무엇인가요?","a":"비트코인(BTC), 이더리움(ETH), 솔라나(SOL), BNB 체인의 BNB, 아발란체(AVAX) 등이 자주 언급됩니다."}],"title":"레이어1(L1)이란? 뜻과 레이어2 차이","description":"레이어1(L1) 블록체인의 뜻과 특징, 트릴레마와 체인별 수수료 차이, 레이어2와의 관계를 예시로 쉽게 설명합니다.","related":[["layer-2","레이어2(Layer 2, L2)","레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다."],["blockchain","블록체인(Blockchain)","블록체인은 거래 기록을 블록 단위로 묶어 시간 순서대로 연결하고, 여러 컴퓨터가 같은 사본을 나눠 보관하는 분산 장부입니다."],["ethereum","이더리움(Ethereum, ETH)","이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["coin-vs-token","코인과 토큰의 차이(Coin vs Token)","코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"ko","term":"토큰 소각(Token Burn)","aka":["소각","Burn","코인 소각"],"short":"토큰 소각은 누구도 꺼낼 수 없는 주소로 토큰을 보내거나 컨트랙트에서 제거해 공급량을 영구적으로 줄이는 것입니다.","body":[["소각은 보통 ",["개인 키","private-key"],"가 존재하지 않는 소각 주소로 토큰을 보내거나, ",["스마트 컨트랙트","smart-contract"],"의 소각 함수를 호출해 이루어집니다. 소각된 토큰은 다시 쓸 수 없으므로 총공급량 또는 ",["유통량","circulating-supply"],"이 줄어듭니다."],["방식은 프로젝트마다 다릅니다. ",["이더리움","ethereum"],"은 2021년 도입된 EIP-1559에 따라 거래 기본 수수료를 자동 소각하고, BNB는 정기적으로 일정 물량을 소각하는 제도를 운영합니다. 거래 수수료 수익으로 토큰을 사들여 소각하는 바이백 앤 번 방식도 있습니다."],"소각은 공급을 줄이는 장치일 뿐 가격 상승을 보장하지 않습니다. 소각량보다 새로 발행되는 양이 많으면 전체 공급은 오히려 늘어날 수 있습니다. 소각 발표를 볼 때는 전체 공급 대비 비율과 발행량을 함께 비교해야 합니다."],"example":["총공급량이 5억 개인 토큰이 분기마다 500만 개를 소각한다고 가정해 보겠습니다. 한 번에 1%씩 줄어드는 셈이고, 1년(4분기)이면 2,000만 개, 약 4%가 줄어듭니다. 하지만 같은 기간 ",["스테이킹","staking"]," 보상으로 3,000만 개가 새로 발행된다면 순공급은 1,000만 개 늘어납니다. 소각 숫자만 보면 놓치기 쉬운 부분입니다."],"mistakes":["소각 소식이 나오면 무조건 가격이 오른다고 기대합니다.","소각량만 보고 같은 기간의 신규 발행량을 확인하지 않습니다.","팀 지갑으로 옮긴 물량을 소각된 것으로 착각합니다."],"faq":[{"q":"소각된 토큰은 되살릴 수 있나요?","a":"제대로 소각된 토큰은 개인 키가 없는 주소에 있거나 컨트랙트에서 제거되어 다시 사용할 수 없습니다. 블록 탐색기에서 소각 주소의 잔고로 확인할 수 있습니다."},{"q":"이더리움은 소각 때문에 공급이 줄어드나요?","a":"기본 수수료 소각량이 신규 발행량보다 많을 때는 줄고, 네트워크 사용이 적어 소각이 적을 때는 늘어납니다. 시기에 따라 방향이 바뀝니다."}],"title":"토큰 소각이란? 뜻과 공급량에 미치는 영향","description":"토큰 소각의 뜻과 방식(소각 주소, EIP-1559, 정기 소각), 소각과 신규 발행을 함께 봐야 하는 이유를 계산 예시로 설명합니다.","related":[["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다."],["circulating-supply","유통량(Circulating Supply)","유통량은 현재 시장에서 실제로 거래될 수 있는 코인의 수량으로, 잠겨 있거나 아직 발행되지 않은 물량은 제외합니다."],["market-capitalization","시가총액(Market Cap)","시가총액은 코인의 현재 가격에 유통 공급량을 곱한 값으로, 시장이 그 자산 전체를 얼마로 평가하고 있는지 보여 주는 지표입니다."],["coin-vs-token","코인과 토큰의 차이(Coin vs Token)","코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"ko","term":"퍼드(FUD)","aka":["FUD","퍼드","공포 조장"],"short":"퍼드(FUD)는 Fear, Uncertainty, Doubt의 약자로, 공포와 불확실성, 의심을 퍼뜨려 시장 참여자의 매도를 부추기는 정보나 분위기를 말합니다.","body":[["퍼드는 해킹 루머, 규제 소식, ",["거래소","centralized-exchange"]," 출금 중단설, 대형 보유자 매도설처럼 불안을 자극하는 이야기에서 시작되는 경우가 많습니다. 그중에는 사실인 경우도 있고, 과장되거나 의도적으로 만든 거짓 정보도 있습니다."],"중요한 것은 모든 나쁜 소식을 퍼드로 무시하지 않는 것입니다. 실제 위험 신호를 퍼드라며 외면하다 큰 손실을 본 사례도 많습니다. 반대로 확인되지 않은 루머에 놀라 저점에 팔아 버리는 것도 흔한 실수입니다.","퍼드를 접했을 때는 출처를 먼저 확인합니다. 프로젝트나 거래소의 공식 공지, 규제 기관 발표, 온체인 데이터처럼 직접 검증할 수 있는 자료가 있는지 보고, 캡처 이미지나 익명 계정의 주장만으로 판단하지 않는 것이 좋습니다."],"example":"어떤 거래소가 출금을 막았다는 소문이 퍼져 보유 코인이 2시간 만에 15% 떨어졌다고 가정해 보겠습니다. 1,000만 원어치를 갖고 있었다면 평가금은 850만 원입니다. 이때 거래소 공식 공지에서 지갑 점검으로 30분간 특정 네트워크만 출금이 중단됐다고 확인되고, 온체인에서도 출금이 재개된 것이 보인다면 루머는 과장된 퍼드였던 셈입니다. 확인 없이 팔았다면 150만 원 손실이 확정됩니다.","mistakes":["출처를 확인하지 않은 루머를 보고 즉시 시장가로 전량 매도합니다.","실제 위험 신호까지 모두 퍼드로 치부하고 무시합니다.","퍼드 분위기를 이용한 가짜 고객센터나 피싱 링크에 접속합니다."],"faq":[{"q":"퍼드는 항상 거짓 정보인가요?","a":"아닙니다. 사실에 기반한 부정적 소식도 퍼드라고 불리는 경우가 있습니다. 내용이 사실인지, 과장됐는지를 공식 자료로 확인하는 것이 중요합니다."},{"q":"퍼드와 포모는 어떤 관계인가요?","a":"퍼드는 공포로 매도를, 포모는 조급함으로 매수를 부추기는 감정입니다. 둘 다 계획 없는 매매로 이어지기 쉽습니다."}],"title":"퍼드(FUD)란? 뜻과 루머 대처법","description":"퍼드(FUD)의 뜻과 대표 사례, 사실과 과장된 루머를 구분하는 확인 방법, 퍼드 국면에서 흔한 실수를 정리합니다.","related":[["fomo","포모(FOMO)","포모(FOMO)는 Fear Of Missing Out의 약자로, 남들이 다 버는 기회를 나만 놓칠까 봐 불안해서 충분한 판단 없이 급하게 매수하는 심리를 말합니다."],["bear-market","하락장(Bear Market, 베어장)","하락장은 가격이 비교적 긴 기간 동안 전반적으로 내려가고 투자 심리가 비관적인 시장 국면으로, 베어장 또는 약세장이라고도 부릅니다."],["fear-and-greed-index","공포 탐욕 지수(Fear and Greed Index)","공포 탐욕 지수는 가격 변동성, 거래량, 소셜 미디어 반응 같은 데이터를 0에서 100 사이 점수로 묶어 시장 심리를 보여 주는 지표입니다."],["on-chain-analysis","온체인 분석","온체인 분석은 블록체인에 공개 기록된 거래, 주소, 잔고 데이터를 읽어 자금 흐름과 네트워크 사용 현황을 파악하는 분석 방법입니다."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"수익을 내주겠다는 사람이 있다면, 먼저 무엇을 요구하는지 보세요."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"ko","term":"스프레드(Bid-Ask Spread)","aka":["매수·매도 호가 차이","호가 스프레드","Spread"],"short":"스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다.","body":["지금 바로 사려면 매도 호가에, 지금 바로 팔려면 매수 호가에 체결해야 합니다. 그래서 같은 순간에 샀다가 바로 팔면 수수료가 없어도 스프레드만큼 손해를 봅니다. 스프레드는 보통 가격 차이 자체나 중간 가격 대비 비율로 표시합니다.",[["거래량","trading-volume"],"이 많고 ",["마켓메이커","market-maker"],"가 활발한 ",["BTC","bitcoin"],"/",["USDT","usdt"]," 같은 페어는 스프레드가 매우 좁습니다. 반면 ",["신규 상장","token-listing"]," 코인, 소형 ",["알트코인","altcoin"],", 새벽 시간대나 급변동 구간에서는 스프레드가 크게 벌어질 수 있습니다."],"스프레드는 거래소의 수수료표에는 나오지 않지만 실제 비용에 포함됩니다. 짧은 시간에 자주 사고파는 단타 매매일수록 스프레드의 영향이 커지므로, 수수료와 함께 확인하는 습관이 필요합니다."],"example":"어떤 코인의 최우선 매수 호가가 0.995달러, 최우선 매도 호가가 1.005달러라고 가정해 보겠습니다. 스프레드는 0.01달러이고 중간 가격 1.000달러 대비 1%입니다. 시장가로 1,000개를 사면 1,005달러를 내고, 즉시 시장가로 팔면 995달러를 받아 수수료 없이도 10달러를 잃습니다. 스프레드가 0.02%인 대형 페어였다면 같은 거래 비용은 약 0.2달러에 불과합니다.","mistakes":["수수료만 비교하고 스프레드가 넓은 마켓에서 자주 거래합니다.","차트에 표시된 최근 체결가를 내가 바로 살 수 있는 가격으로 착각합니다.","변동성이 큰 시간대에 스프레드가 벌어진 상태로 시장가 주문을 넣습니다."],"faq":[{"q":"스프레드가 넓으면 왜 불리한가요?","a":"즉시 체결하려면 상대 호가에 맞춰야 하므로 사는 순간부터 그 차이만큼 손실이 생긴 상태로 시작합니다. 자주 거래할수록 누적 비용이 커집니다."},{"q":"스프레드를 줄이는 방법이 있나요?","a":"유동성이 높은 페어와 시간대를 고르고, 급하지 않다면 지정가 주문으로 원하는 가격에 걸어 두는 방법이 있습니다. 다만 지정가는 체결되지 않을 수도 있습니다."}],"title":"스프레드란? 매수·매도 호가 차이 뜻","description":"스프레드(bid-ask spread)의 뜻과 계산법, 스프레드가 넓어지는 상황, 수수료표에 없는 숨은 거래 비용을 줄이는 방법을 설명합니다.","related":[["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["market-maker","마켓메이커(Market Maker)","마켓메이커는 매수 호가와 매도 호가를 동시에 꾸준히 걸어 두어 다른 사람이 언제든 거래할 수 있도록 유동성을 공급하는 참여자입니다."],["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"ko","term":"슬리피지(Slippage)","aka":["Slippage","미끄러짐"],"short":"슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다.","body":[[["시장가 주문","market-order"],"은 ",["호가창","order-book"],"에 있는 물량을 순서대로 소진하며 체결됩니다. 주문 크기가 최우선 호가의 물량보다 크면 다음 가격대까지 넘어가면서 평균 체결가가 불리해지는데, 이것이 슬리피지입니다. 주문 사이에 가격이 급변해도 슬리피지가 생깁니다."],[["탈중앙화 거래소(DEX)","dex"],"에서는 ",["유동성 풀","liquidity-pool"],"의 크기 대비 주문이 클수록 가격 영향이 커집니다. 그래서 DEX에서는 슬리피지 허용 범위(예: 0.5%)를 설정하고, 실제 체결가가 이 범위를 벗어나면 거래가 취소되도록 합니다."],["슬리피지를 줄이려면 ",["유동성","liquidity"],"이 풍부한 페어를 고르고, 큰 주문은 여러 번 나눠 넣거나 ",["지정가 주문","limit-order"],"을 쓰는 방법이 있습니다. 선물 시장에서 손절이 시장가로 실행될 때도 급변동 구간에서는 슬리피지가 발생할 수 있습니다."]],"example":"BTC 가격이 64,000 USDT로 표시된 상태에서 시장가로 3 BTC를 산다고 가정해 보겠습니다. 최우선 매도 호가에 1 BTC, 64,050 USDT에 1 BTC, 64,150 USDT에 1 BTC가 있다면 총 비용은 192,200 USDT, 평균 체결가는 약 64,067 USDT입니다. 예상 가격 대비 약 0.1%의 슬리피지가 생겼고, 금액으로는 약 200 USDT입니다.","mistakes":["거래량이 적은 코인에 큰 금액을 한 번에 시장가로 주문합니다.","DEX에서 거래가 실패한다는 이유로 슬리피지 허용 범위를 지나치게 높게 설정합니다.","손절 주문은 항상 설정한 가격에 정확히 체결된다고 믿습니다."],"faq":[{"q":"슬리피지와 스프레드는 같은 건가요?","a":"다릅니다. 스프레드는 최우선 매수·매도 호가의 차이이고, 슬리피지는 예상 가격과 실제 평균 체결가의 차이입니다. 스프레드는 슬리피지를 구성하는 요소 중 하나입니다."},{"q":"DEX 슬리피지는 몇 퍼센트로 설정해야 하나요?","a":"정답은 없지만 유동성이 풍부한 주요 토큰은 낮은 값으로도 충분한 경우가 많습니다. 허용 범위를 높이면 체결은 쉬워지지만 불리한 가격에 체결되거나 샌드위치 공격을 당할 위험도 커집니다."}],"title":"슬리피지란? 뜻과 슬리피지 줄이는 법","description":"슬리피지의 뜻과 발생 원리, 시장가 주문과 DEX 슬리피지 허용 범위의 의미, 슬리피지를 줄이는 주문 방법을 설명합니다.","related":[["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다."],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["amm","자동화 마켓 메이커(AMM)","자동화 마켓 메이커(AMM)는 매수자와 매도자를 호가창에서 맞추는 대신 유동성 풀에 쌓인 두 토큰의 비율과 수학 공식으로 가격을 자동으로 정하는 거래 방식입니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"ko","term":"트레일링 스탑(Trailing Stop)","aka":["트레일링스탑","추적 손절","Trailing Stop"],"short":"트레일링 스탑은 가격이 유리하게 움직이면 손절 가격이 일정 간격을 유지하며 함께 따라 올라가고, 가격이 그 간격만큼 되돌리면 포지션을 정리하는 주문입니다.","body":["트레일링 스탑은 고정된 손절가 대신 최고가(숏이면 최저가)에서 일정 비율이나 금액만큼 떨어진 지점을 손절가로 계속 갱신합니다. 가격이 오르면 손절가도 올라가지만, 가격이 내려갈 때는 손절가가 내려가지 않습니다.",["추세가 이어질 때 이익을 끝까지 따라가면서도, 방향이 바뀌면 일부 이익을 지킨 채 빠져나올 수 있다는 것이 장점입니다. 일부 ",["거래소","centralized-exchange"],"에서는 활성화 가격을 정해, 가격이 그 수준에 도달한 뒤부터 추적을 시작하게 할 수도 있습니다."],["간격 설정이 핵심입니다. 너무 좁으면 일상적인 흔들림에도 바로 청산되고, 너무 넓으면 지킬 수 있는 이익이 줄어듭니다. 코인의 평소 변동 폭을 참고해 정하는 것이 일반적이며, 실행은 대개 ",["시장가","market-order"],"라 ",["슬리피지","slippage"],"가 생길 수 있습니다."]],"example":"BTC를 50,000 USDT에 사고 5% 트레일링 스탑을 걸었다고 가정해 보겠습니다. 처음 손절가는 47,500 USDT입니다. 가격이 58,000 USDT까지 오르면 손절가는 58,000의 95%인 55,100 USDT로 올라갑니다. 이후 가격이 55,100 USDT로 되돌리면 주문이 실행되어, 매수가 대비 약 10.2%의 이익을 확정합니다(수수료와 슬리피지 제외).","mistakes":["변동성이 큰 코인에 1~2%처럼 좁은 간격을 설정해 바로 청산됩니다.","트레일링 스탑이 가격 하락 때도 손절가를 낮춰 준다고 오해합니다.","활성화 가격 조건을 설정해 놓고 아직 추적이 시작되지 않았다는 사실을 모릅니다."],"faq":[{"q":"트레일링 스탑은 현물에서도 쓸 수 있나요?","a":"거래소에 따라 다릅니다. 선물에서만 제공하는 곳도 있고 현물에서도 지원하는 곳도 있으니 주문 유형 목록을 확인해야 합니다."},{"q":"트레일링 스탑 비율은 몇 %가 적당한가요?","a":"정답은 없습니다. 코인의 평소 일일 변동 폭보다 너무 좁지 않게 잡고, 추세를 얼마나 길게 따라가고 싶은지에 따라 조절합니다."}],"title":"트레일링 스탑이란? 뜻과 설정 방법","description":"트레일링 스탑의 뜻과 작동 원리, 간격(콜백 비율)과 활성화 가격 설정법, 이익을 지키는 계산 예시를 정리합니다.","related":[["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."],["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."],["stop-limit-order","스탑 리밋 주문(Stop-Limit Order)","스탑 리밋 주문은 가격이 트리거(스탑) 가격에 도달하면 미리 정한 지정가 주문이 호가창에 올라가도록 하는 조건부 주문입니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"익절과 손절은 계획이지 보험이 아니다"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"ko","term":"마크 가격(Mark Price)","aka":["표시 가격","mark price","마크프라이스"],"short":"마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다.","body":[["선물 시장의 ",["최근 체결가","last-price"],"는 큰 주문 하나에도 순간적으로 튈 수 있습니다. 이 가격으로 청산을 판단하면 가격을 잠깐 밀어 올리거나 내려서 다른 사람들을 청산시키는 일이 쉬워집니다. 마크 가격은 이를 막기 위한 장치입니다."],["보통 마크 가격은 여러 ",["거래소","centralized-exchange"]," 현물 가격을 평균한 ",["지수 가격","index-price"],"에, ",["펀딩비","funding-rate"],"나 선물과 현물의 가격 차이를 반영해 계산합니다. 구체적인 공식은 거래소마다 다릅니다."],["앱에서 ",["미실현 손익","unrealized-pnl"],"과 청산 여부는 마크 가격 기준으로, 체결은 실제 호가 기준으로 이루어집니다. 그래서 차트에 긴 꼬리가 나와도 청산되지 않거나, 반대로 체결가가 ",["청산가","liquidation-price"],"에 닿지 않았는데 청산되는 일이 생길 수 있습니다."]],"example":"BTC 무기한 선물에서 청산가가 57,000 USDT인 롱 포지션을 들고 있다고 가정해 보겠습니다. 큰 시장가 매도 때문에 선물 최근 체결가가 몇 초 동안 56,800 USDT까지 떨어졌지만, 여러 현물 거래소 가격을 반영한 마크 가격은 57,400 USDT에 머물렀습니다. 이 경우 마크 가격이 청산가에 닿지 않았으므로 포지션은 청산되지 않습니다. 반대로 마크 가격이 57,000 이하로 내려가면 체결가와 상관없이 청산됩니다.","mistakes":["차트의 최근 체결가만 보고 청산 위험을 판단합니다.","미실현 손익이 최근 체결가로 계산된다고 생각해 화면의 손익이 예상과 다르다고 혼란스러워합니다.","손절 주문의 기준 가격을 마크 가격으로 할지 최근 체결가로 할지 설정할 수 있다는 것을 모릅니다."],"faq":[{"q":"마크 가격과 최근 체결가는 왜 다른가요?","a":"최근 체결가는 해당 거래소 선물 시장에서 마지막으로 체결된 가격이고, 마크 가격은 여러 현물 거래소 가격을 바탕으로 계산한 공정 가격입니다. 급변 구간에는 두 가격 차이가 커질 수 있습니다."},{"q":"청산은 어떤 가격으로 판단하나요?","a":"대부분의 거래소는 마크 가격으로 청산 여부를 판단합니다. 정확한 기준은 거래소의 계약 명세에서 확인할 수 있습니다."}],"title":"마크 가격이란? 최근 체결가와의 차이","description":"선물 거래의 마크 가격 뜻, 지수 가격과의 관계, 청산과 미실현 손익이 마크 가격으로 계산되는 이유를 설명합니다.","related":[["index-price","지수 가격(Index Price)","지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다."],["liquidation-price","청산가(Liquidation Price)","청산가는 마크 가격이 그 수준에 닿으면 증거금이 유지 증거금 아래로 떨어져 포지션이 강제청산되는 가격입니다."],["last-price","최근 체결가(Last Price)","최근 체결가는 해당 거래소 시장에서 가장 마지막으로 실제 체결된 거래의 가격으로, 차트와 시세 화면에 현재가로 표시되는 값입니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"강제 청산: 강제 종료 버튼은 누가 눌렀는가?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"ko","term":"간편 전환(Convert)","aka":["코인 전환","즉시 교환","Convert","플래시 스왑"],"short":"간편 전환은 호가창에서 주문을 내지 않고, 거래소가 제시한 견적 가격으로 한 코인을 다른 코인으로 즉시 바꿔 주는 기능입니다.","body":[["바꿀 코인과 수량을 입력하면 몇 초 동안 유효한 견적이 나오고, 확인을 누르면 그 가격에 체결됩니다. ",["지정가","limit-order"],"와 ",["시장가","market-order"],"를 몰라도 되고, 소수 코인끼리 바꿀 때도 중간 단계를 자동으로 처리해 주기 때문에 초보자가 많이 씁니다."],["거래 수수료가 없다고 표시되는 경우가 많지만, 비용은 견적 가격 안에 ",["스프레드","bid-ask-spread"],"로 들어가 있습니다. 같은 시각 현물 ",["호가창","order-book"],"의 가격과 비교하면 몇 퍼센트 차이가 나는 경우도 있습니다. ",["유동성","liquidity"],"이 낮은 코인일수록 이 차이가 커집니다."],"소액을 빠르게 바꿀 때는 편리하지만, 금액이 크거나 거래가 잦다면 현물 시장에서 지정가 주문을 쓰는 편이 대개 저렴합니다. 바꾸기 전에 견적 화면의 환율과 현물 가격을 한 번 비교해 보세요."],"example":["SOL 10개를 USDT로 바꾸려 하는데 현물 호가창의 최우선 매수 호가가 150 USDT라고 가정합니다. 간편 전환 견적은 1 SOL당 149.1 USDT로 표시됩니다. 전환하면 1,491 USDT를 받고, 호가창에서 시장가로 팔았다면 수수료 0.1%를 내고도 약 1,498.5 USDT를 받았을 것입니다. 수수료 0%라고 표시된 전환이 실제로는 약 7.5 ",["USDT","usdt"],", 0.5% 더 비쌌던 셈입니다."],"mistakes":["수수료 0% 표시만 보고 견적 가격에 포함된 스프레드를 확인하지 않습니다.","큰 금액을 유동성 낮은 코인으로 한 번에 전환합니다.","견적 유효 시간이 지난 뒤 다시 나온 가격을 확인하지 않고 바로 확인을 누릅니다."],"faq":[{"q":"간편 전환은 현물 거래보다 비싼가요?","a":"표시 수수료는 없더라도 견적 가격에 스프레드가 포함되어 있어 현물 거래보다 비싼 경우가 많습니다. 같은 시각 가격을 비교해 보면 알 수 있습니다."},{"q":"간편 전환에도 슬리피지가 있나요?","a":"견적이 확정된 가격으로 체결되므로 일반적인 슬리피지는 없습니다. 대신 그 위험이 견적 가격에 미리 반영됩니다."}],"title":"간편 전환(Convert)이란? 숨은 비용과 현물 거래 비교","description":"거래소 간편 전환(Convert)의 뜻, 수수료 0%에 숨은 스프레드 비용, 현물 거래와의 비교 계산을 설명합니다.","related":[["spot-trading","현물 거래(Spot Trading)","현물 거래는 코인을 현재 가격에 실제로 사고팔아 즉시 소유권이 넘어가는 거래 방식으로, 산 코인은 바로 내 계정 잔고에 들어옵니다."],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다."],["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다."],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"첫 현물 거래: 100에서 0.002 BTC까지"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"ko","term":"토큰화 주식(Tokenized stocks)","aka":["토큰 증권","주식 토큰","Tokenized stocks"],"short":"토큰화 주식은 실제 주식이나 그 가격을 따라가는 권리를 블록체인 토큰으로 발행해 암호화폐처럼 지갑과 거래소에서 거래할 수 있게 만든 자산입니다.","body":["발행 방식에 따라 성격이 다릅니다. 발행사가 실제 주식을 보관하고 그만큼 토큰을 발행하는 1대1 뒷받침형이 있고, 가격만 따라가는 파생형이 있습니다. 같은 애플 토큰이라도 주식에 대한 법적 권리가 있는지, 배당이 반영되는지, 의결권이 있는지는 발행 구조마다 다릅니다.",["장점은 24시간 거래, 소수 단위 매수, ",["스테이블코인","stablecoin"],"으로 바로 결제할 수 있다는 점입니다. 하지만 주식 시장이 닫혀 있는 시간에는 기준 가격이 없어 토큰 가격이 실제 주가와 벌어질 수 있고, 다음 개장 때 한꺼번에 조정됩니다."],["증권으로 분류되는 상품이라 거주 국가에 따라 이용이 제한될 수 있습니다. 발행사와 수탁 기관, 상환 가능 여부, 거래 가능 지역을 확인하고, ",["무기한 선물","perpetual-futures"],"로 주가를 추종하는 ",["주식 무기한 선물","stock-perpetuals"],"과 혼동하지 않아야 합니다."]],"example":["어떤 주식이 금요일 종가 200달러이고, 1대1 뒷받침형 토큰을 0.5개, 즉 100 USDT어치 샀다고 가정합니다. 주말에 회사 관련 뉴스가 나오자 토큰이 210 USDT로 거래되어 평가액이 105 USDT가 됩니다. 그런데 월요일 개장 시 실제 주가가 204달러에서 시작하면 토큰 가격도 204 ",["USDT","usdt"]," 근처로 수렴해 평가액은 102 USDT로 내려갑니다. 주말 가격은 추정에 가깝다는 점을 보여 줍니다."],"mistakes":["토큰을 보유하면 주주와 같은 권리를 자동으로 가진다고 생각합니다.","증시 휴장 시간의 토큰 가격을 실제 주가와 같은 것으로 봅니다.","거주 국가에서 이용이 제한되는 상품인지 확인하지 않습니다."],"faq":[{"q":"토큰화 주식도 배당을 받나요?","a":"발행 구조에 따라 다릅니다. 배당을 토큰 수량이나 스테이블코인으로 반영하는 상품도 있고, 반영하지 않는 상품도 있습니다."},{"q":"토큰화 주식과 주식 무기한 선물은 무엇이 다른가요?","a":"토큰화 주식은 자산을 보유하는 방식이고, 주식 무기한 선물은 만기 없는 파생 계약으로 펀딩비와 레버리지, 청산이 따릅니다."}],"title":"토큰화 주식이란? 블록체인으로 주식 거래하는 구조","description":"토큰화 주식의 뜻, 1대1 뒷받침형과 파생형의 차이, 휴장 시간 가격 괴리와 이용 전 확인할 점을 설명합니다.","related":[["stock-perpetuals","주식 무기한 선물","주식 무기한 선물은 테슬라나 엔비디아 같은 주식의 가격을 추종하는 만기 없는 선물 계약으로, USDT 증거금과 레버리지로 롱과 숏을 거래합니다."],["real-world-assets","실물자산 토큰화(RWA)","RWA는 국채, 주식, 금, 부동산, 대출 채권처럼 블록체인 밖에 존재하는 실물·금융 자산의 소유권이나 수익권을 토큰으로 발행한 것을 말합니다."],["spot-bitcoin-etf","비트코인 현물 ETF","비트코인 현물 ETF는 실제 비트코인을 보유하고 그 가격을 따라가도록 설계된 상장지수펀드로, 증권 계좌에서 주식처럼 사고팔 수 있습니다."],["usdc","USDC(USD 코인)","USDC는 미국 기업 서클(Circle)이 발행하는 미국 달러 연동 스테이블코인으로, 현금과 단기 미국 국채 등 준비자산으로 1대1 가치를 뒷받침합니다."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
